/* Azerbaijan's 14 economic regions (2021 division) as SVG paths.
 *
 * Generated by backend-free tooling, not by hand: the 79 districts and cities of
 * geoBoundaries' AZE ADM2 boundaries (from Wikipedia, CC BY-SA 3.0,
 * https://www.geoboundaries.org) were tagged with their economic region, merged with
 * mapshaper, simplified and projected (equirectangular, scaled for latitude
 * 40.16°). This file is an adaptation of that data and is shared under the same
 * licence, CC BY-SA 3.0; the code around it is not.
 *
 * Do not edit the paths by hand: regenerate them instead.
 */

export type RegionShape = {
  key: string;
  name: string;
  nameAz: string;
  districts: string[];
  /** SVG path in the 1000 x 794.7 viewBox. */
  d: string;
  /** Area-weighted centre, for labels and the region's pin. */
  cx: number;
  cy: number;
};

export const AZ_VIEWBOX = { width: 1000, height: 794.7 };

const LON_MIN = 44.765200;
const LAT_MAX = 41.921400;
const KX = 0.76428867;
const SCALE = 218.313744;
const PAD = 12.0;

/** A longitude and latitude on the same projection as the region paths. */
export function project(lng: number, lat: number): [number, number] {
  return [PAD + (lng - LON_MIN) * KX * SCALE, PAD + (LAT_MAX - lat) * SCALE];
}

